-- ----------------------------------------------------------------------------

create or replace function public.get_my_tenant_id()
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  claims jsonb;
  raw text;
  fallback_tenant uuid;
begin
  claims := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb,
    '{}'::jsonb
  );

  raw := coalesce(claims ->> 'tenant_id', claims -> 'app_metadata' ->> 'tenant_id');

  if raw is not null
     and raw ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return raw::uuid;
  end if;

  select p.tenant_id into fallback_tenant
  from public.profiles p
  where p.id = auth.uid();

  if fallback_tenant is not null then
    return fallback_tenant;
  end if;

  select tm.tenant_id into fallback_tenant
  from public.tenant_memberships tm
  where tm.profile_id = auth.uid()
  order by tm.created_at asc
  limit 1;

  return fallback_tenant;
end;
$$;

create or replace function public.is_platform_admin()
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  claims jsonb;
begin
  claims := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb,
    '{}'::jsonb
  );

  if coalesce(
    claims -> 'app_metadata' ->> 'role',
    claims ->> 'role'
  ) = 'admin' then
    return true;
  end if;

  return exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'admin'
  );
end;
$$;

create or replace function public.current_profile_role()
returns public.app_role
language sql
stable
security definer
set search_path = public
as $$
  select role from public.profiles where id = auth.uid();
$$;

