-- ============================================================================
-- Fides — Customer records, internal notes, and reviews
-- Migration: 00006_customers.sql
--
-- Depends on public.tenants, public.profiles, public.tenant_memberships,
-- public.appointments, public.staff_members, public.is_platform_admin(),
-- and public.set_updated_at().
-- ============================================================================

BEGIN;

-- 1. Review status enum
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_type t
        JOIN pg_namespace n ON n.oid = t.typnamespace
        WHERE t.typname = 'review_status' AND n.nspname = 'public'
    ) THEN
        CREATE TYPE public.review_status AS ENUM ('pending', 'published', 'hidden');
    END IF;
END
$$;

-- 2. Customer records. Multiple guest rows may have NULL profile_id.
CREATE TABLE IF NOT EXISTS public.customers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    profile_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
    full_name TEXT NOT NULL,
    email TEXT,
    phone TEXT,
    birthday DATE,
    marketing_opt_in BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT customers_tenant_profile_key UNIQUE (tenant_id, profile_id),
    CONSTRAINT customers_tenant_id_id_key UNIQUE (tenant_id, id),
    CONSTRAINT customers_full_name_nonblank CHECK (length(btrim(full_name)) > 0)
);

CREATE INDEX IF NOT EXISTS customers_tenant_email_idx
    ON public.customers (tenant_id, email) WHERE email IS NOT NULL;
CREATE INDEX IF NOT EXISTS customers_tenant_phone_idx
    ON public.customers (tenant_id, phone) WHERE phone IS NOT NULL;
CREATE INDEX IF NOT EXISTS customers_profile_id_idx
    ON public.customers (profile_id) WHERE profile_id IS NOT NULL;

-- 3. Internal notes: tenant-aware customer FK prevents cross-tenant references.
CREATE TABLE IF NOT EXISTS public.customer_notes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    customer_id UUID NOT NULL,
    author_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,
    body TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT customer_notes_body_nonblank CHECK (length(btrim(body)) > 0),
    CONSTRAINT customer_notes_customer_fkey
        FOREIGN KEY (tenant_id, customer_id)
        REFERENCES public.customers (tenant_id, id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS customer_notes_customer_created_idx
    ON public.customer_notes (tenant_id, customer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS customer_notes_author_idx
    ON public.customer_notes (author_id);

-- 4. Reviews. Composite FKs ensure referenced rows belong to the same tenant.
-- One review per appointment; PostgreSQL permits multiple NULL appointment_ids.
CREATE TABLE IF NOT EXISTS public.reviews (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    customer_id UUID NOT NULL,
    appointment_id UUID,
    staff_id UUID,
    rating SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment TEXT,
    status public.review_status NOT NULL DEFAULT 'pending',
    published_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT reviews_tenant_id_id_key UNIQUE (tenant_id, id),
    CONSTRAINT reviews_one_per_appointment_key UNIQUE (appointment_id),
    CONSTRAINT reviews_customer_fkey
        FOREIGN KEY (tenant_id, customer_id)
        REFERENCES public.customers (tenant_id, id) ON DELETE CASCADE,
    CONSTRAINT reviews_appointment_fkey
        FOREIGN KEY (tenant_id, appointment_id)
        REFERENCES public.appointments (tenant_id, id)
        ON DELETE SET NULL (appointment_id),
    CONSTRAINT reviews_staff_fkey
        FOREIGN KEY (tenant_id, staff_id)
        REFERENCES public.staff_members (tenant_id, id)
        ON DELETE SET NULL (staff_id),
    CONSTRAINT reviews_published_timestamp_check
        CHECK (status <> 'published' OR published_at IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS reviews_tenant_status_published_idx
    ON public.reviews (tenant_id, status, published_at DESC);
CREATE INDEX IF NOT EXISTS reviews_customer_created_idx
    ON public.reviews (tenant_id, customer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS reviews_staff_created_idx
    ON public.reviews (tenant_id, staff_id, created_at DESC) WHERE staff_id IS NOT NULL;

-- 5. Resolve deferred appointment -> customer FK. Guest bookings remain valid.
ALTER TABLE public.appointments
    DROP CONSTRAINT IF EXISTS appointments_customer_id_fkey;
ALTER TABLE public.appointments
    ADD CONSTRAINT appointments_customer_id_fkey
    FOREIGN KEY (customer_id) REFERENCES public.customers (id) ON DELETE SET NULL;
COMMENT ON COLUMN public.appointments.customer_id IS
    'Nullable customer record reference; NULL supports guest bookings and customer deletion.';

-- 6. updated_at triggers
DROP TRIGGER IF EXISTS customers_set_updated_at ON public.customers;
CREATE TRIGGER customers_set_updated_at
    BEFORE UPDATE ON public.customers
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
DROP TRIGGER IF EXISTS reviews_set_updated_at ON public.reviews;
CREATE TRIGGER reviews_set_updated_at
    BEFORE UPDATE ON public.reviews
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- 7. Enable RLS
ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.customer_notes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;

-- 8. Customers: tenant operational access plus customer self-service.
DROP POLICY IF EXISTS customers_operational_manage ON public.customers;
CREATE POLICY customers_operational_manage ON public.customers
FOR ALL TO authenticated
USING (
    public.is_platform_admin()
    OR EXISTS (
        SELECT 1 FROM public.tenant_memberships tm
        WHERE tm.tenant_id = customers.tenant_id
          AND tm.profile_id = auth.uid()
          AND tm.role IN ('owner', 'admin', 'receptionist', 'staff')
    )
)
WITH CHECK (
    public.is_platform_admin()
    OR EXISTS (
        SELECT 1 FROM public.tenant_memberships tm
        WHERE tm.tenant_id = customers.tenant_id
          AND tm.profile_id = auth.uid()
          AND tm.role IN ('owner', 'admin', 'receptionist', 'staff')
    )
);
DROP POLICY IF EXISTS customers_self_select ON public.customers;
CREATE POLICY customers_self_select ON public.customers
FOR SELECT TO authenticated USING (profile_id = auth.uid());
DROP POLICY IF EXISTS customers_self_update ON public.customers;
CREATE POLICY customers_self_update ON public.customers
FOR UPDATE TO authenticated
USING (profile_id = auth.uid())
WITH CHECK (profile_id = auth.uid());

-- 9. Notes are accessible only to operational members / platform admins.
DROP POLICY IF EXISTS customer_notes_operational_manage ON public.customer_notes;
CREATE POLICY customer_notes_operational_manage ON public.customer_notes
FOR ALL TO authenticated
USING (
    public.is_platform_admin()
    OR EXISTS (
        SELECT 1 FROM public.tenant_memberships tm
        WHERE tm.tenant_id = customer_notes.tenant_id
          AND tm.profile_id = auth.uid()
          AND tm.role IN ('owner', 'admin', 'receptionist', 'staff')
    )
)
WITH CHECK (
    public.is_platform_admin()
    OR EXISTS (
        SELECT 1 FROM public.tenant_memberships tm
        WHERE tm.tenant_id = customer_notes.tenant_id
          AND tm.profile_id = auth.uid()
          AND tm.role IN ('owner', 'admin', 'receptionist', 'staff')
    )
);

-- 10. Reviews: public published-only reads; owner/admin can see all and moderate.
DROP POLICY IF EXISTS reviews_public_read_published ON public.reviews;
CREATE POLICY reviews_public_read_published ON public.reviews
FOR SELECT TO anon, authenticated USING (status = 'published');
DROP POLICY IF EXISTS reviews_owner_admin_read_all ON public.reviews;
CREATE POLICY reviews_owner_admin_read_all ON public.reviews
FOR SELECT TO authenticated
USING (
    public.is_platform_admin()
    OR EXISTS (
        SELECT 1 FROM public.tenant_memberships tm
        WHERE tm.tenant_id = reviews.tenant_id
          AND tm.profile_id = auth.uid()
          AND tm.role IN ('owner', 'admin')
    )
);
DROP POLICY IF EXISTS reviews_customer_insert_completed_appointment ON public.reviews;
CREATE POLICY reviews_customer_insert_completed_appointment ON public.reviews
FOR INSERT TO authenticated
WITH CHECK (
    status = 'pending'
    AND published_at IS NULL
    AND appointment_id IS NOT NULL
    AND EXISTS (
        SELECT 1
        FROM public.customers c
        JOIN public.appointments a
          ON a.tenant_id = c.tenant_id AND a.customer_id = c.id
        WHERE c.id = reviews.customer_id
          AND c.tenant_id = reviews.tenant_id
          AND c.profile_id = auth.uid()
          AND a.id = reviews.appointment_id
          AND a.status = 'completed'
          AND (reviews.staff_id IS NULL OR a.staff_id = reviews.staff_id)
    )
);
DROP POLICY IF EXISTS reviews_owner_admin_moderate ON public.reviews;
CREATE POLICY reviews_owner_admin_moderate ON public.reviews
FOR UPDATE TO authenticated
USING (
    public.is_platform_admin()
    OR EXISTS (
        SELECT 1 FROM public.tenant_memberships tm
        WHERE tm.tenant_id = reviews.tenant_id
          AND tm.profile_id = auth.uid()
          AND tm.role IN ('owner', 'admin')
    )
)
WITH CHECK (
    public.is_platform_admin()
    OR EXISTS (
        SELECT 1 FROM public.tenant_memberships tm
        WHERE tm.tenant_id = reviews.tenant_id
          AND tm.profile_id = auth.uid()
          AND tm.role IN ('owner', 'admin')
    )
);

-- 11. Least-privilege grants. RLS alone does not replace SQL privileges.
GRANT USAGE ON SCHEMA public TO anon, authenticated;
REVOKE ALL ON public.customers, public.customer_notes, public.reviews FROM anon, authenticated;

-- Authenticated staff CRUD is subject to RLS. Self-service can update only
-- these allowed fields; tenant_id/profile_id and timestamps are not writable.
GRANT SELECT, INSERT, DELETE ON public.customers TO authenticated;
GRANT UPDATE (full_name, email, phone, birthday, marketing_opt_in)
ON public.customers TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.customer_notes TO authenticated;
GRANT SELECT ON public.reviews TO anon, authenticated;
GRANT INSERT ON public.reviews TO authenticated;
GRANT UPDATE (status, published_at) ON public.reviews TO authenticated;

COMMIT;

-- No Realtime publication changes are required for this migration.

-- >>>>>>>>>> 00007_walkins.sql >>>>>>>>>>
-- ============================================================================
-- Fides — Walk-in waitlist migration (00007)
-- Depends on the baseline, catalog, staff, appointments, and customer migrations.
-- Uses tenant_memberships.role values directly; does not depend on public.app_role.
-- ============================================================================

BEGIN;

-- 1. Waitlist lifecycle
DO $$
BEGIN
    CREATE TYPE public.waitlist_status AS ENUM (
        'waiting',
        'notified',
        'converted',
        'expired',
        'cancelled'
    );
EXCEPTION
    WHEN duplicate_object THEN NULL;
END
$$;

-- Allow authenticated users to use the waitlist status enum.
GRANT USAGE ON TYPE public.waitlist_status TO authenticated;

-- 2. Walk-in / waitlist entries
CREATE TABLE IF NOT EXISTS public.waitlist_entries (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL
        REFERENCES public.tenants(id) ON DELETE CASCADE,
    customer_id UUID,
    guest_name TEXT,
    guest_phone TEXT,
    service_id UUID,
    staff_id UUID,
    status public.waitlist_status NOT NULL DEFAULT 'waiting',
    joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    notified_at TIMESTAMPTZ,
    converted_appointment_id UUID,
    notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT waitlist_entries_tenant_id_id_key UNIQUE (tenant_id, id),

    CONSTRAINT waitlist_entries_customer_fkey
        FOREIGN KEY (tenant_id, customer_id)
        REFERENCES public.customers(tenant_id, id)
        ON DELETE RESTRICT,

    CONSTRAINT waitlist_entries_service_fkey
        FOREIGN KEY (tenant_id, service_id)
        REFERENCES public.services(tenant_id, id)
        ON DELETE RESTRICT,

    CONSTRAINT waitlist_entries_staff_fkey
        FOREIGN KEY (tenant_id, staff_id)
        REFERENCES public.staff_members(tenant_id, id)
        ON DELETE RESTRICT,

    CONSTRAINT waitlist_entries_identity_check CHECK (
        customer_id IS NOT NULL
        OR NULLIF(BTRIM(guest_name), '') IS NOT NULL
    ),

    CONSTRAINT waitlist_entries_guest_name_check CHECK (
        guest_name IS NULL OR NULLIF(BTRIM(guest_name), '') IS NOT NULL
    ),

    CONSTRAINT waitlist_entries_guest_phone_check CHECK (
        guest_phone IS NULL OR NULLIF(BTRIM(guest_phone), '') IS NOT NULL
    ),

    CONSTRAINT waitlist_entries_notified_at_check CHECK (
        status <> 'notified' OR notified_at IS NOT NULL
    ),

    CONSTRAINT waitlist_entries_conversion_check CHECK (
        (status = 'converted' AND converted_appointment_id IS NOT NULL)
        OR
        (status <> 'converted' AND converted_appointment_id IS NULL)
    )
);

-- 3. Link appointments back to the originating waitlist entry.
-- The reciprocal FK is added after the waitlist table exists.
ALTER TABLE public.appointments
    ADD COLUMN IF NOT EXISTS waitlist_entry_id UUID;

CREATE UNIQUE INDEX IF NOT EXISTS appointments_tenant_waitlist_entry_uidx
    ON public.appointments (tenant_id, waitlist_entry_id)
    WHERE waitlist_entry_id IS NOT NULL;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'appointments_waitlist_entry_fkey'
          AND conrelid = 'public.appointments'::regclass
    ) THEN
        ALTER TABLE public.appointments
            ADD CONSTRAINT appointments_waitlist_entry_fkey
            FOREIGN KEY (tenant_id, waitlist_entry_id)
            REFERENCES public.waitlist_entries(tenant_id, id)
            ON DELETE SET NULL (waitlist_entry_id);
    END IF;
END
$$;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'waitlist_entries_converted_appointment_fkey'
          AND conrelid = 'public.waitlist_entries'::regclass
    ) THEN
        ALTER TABLE public.waitlist_entries
            ADD CONSTRAINT waitlist_entries_converted_appointment_fkey
            FOREIGN KEY (tenant_id, converted_appointment_id)
            REFERENCES public.appointments(tenant_id, id)
            ON DELETE RESTRICT;
    END IF;
END
$$;

CREATE UNIQUE INDEX IF NOT EXISTS waitlist_entries_tenant_converted_appointment_uidx
    ON public.waitlist_entries (tenant_id, converted_appointment_id)
    WHERE converted_appointment_id IS NOT NULL;

COMMENT ON COLUMN public.appointments.waitlist_entry_id IS
    'Optional originating waitlist entry; conversion should create the appointment and update the entry in one transaction.';

-- 4. Indexes for queue display and tenant-scoped lookups
CREATE INDEX IF NOT EXISTS waitlist_entries_tenant_status_joined_idx
    ON public.waitlist_entries (tenant_id, status, joined_at);

CREATE INDEX IF NOT EXISTS waitlist_entries_tenant_customer_idx
    ON public.waitlist_entries (tenant_id, customer_id)
    WHERE customer_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS waitlist_entries_tenant_service_idx
    ON public.waitlist_entries (tenant_id, service_id)
    WHERE service_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS waitlist_entries_tenant_staff_idx
    ON public.waitlist_entries (tenant_id, staff_id)
    WHERE staff_id IS NOT NULL;

-- 5. Enforce the intended lifecycle:
-- waiting -> notified / converted / expired / cancelled
-- notified -> converted / expired / cancelled
-- converted, expired, and cancelled are terminal states.
CREATE OR REPLACE FUNCTION public.enforce_waitlist_status_transition()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
    IF NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;

    IF OLD.status = 'waiting'
       AND NEW.status IN ('notified', 'converted', 'expired', 'cancelled') THEN
        RETURN NEW;
    END IF;

    IF OLD.status = 'notified'
       AND NEW.status IN ('converted', 'expired', 'cancelled') THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'Invalid waitlist status transition: % -> %',
        OLD.status, NEW.status
        USING ERRCODE = 'check_violation';
END;
$$;

CREATE OR REPLACE FUNCTION public.set_waitlist_notified_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
    IF NEW.status = 'notified'
       AND OLD.status IS DISTINCT FROM 'notified'
       AND NEW.notified_at IS NULL THEN
        NEW.notified_at := NOW();
    END IF;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS enforce_waitlist_status_transition
    ON public.waitlist_entries;

CREATE TRIGGER enforce_waitlist_status_transition
    BEFORE UPDATE OF status ON public.waitlist_entries
    FOR EACH ROW
    EXECUTE FUNCTION public.enforce_waitlist_status_transition();

DROP TRIGGER IF EXISTS set_waitlist_notified_at
    ON public.waitlist_entries;

CREATE TRIGGER set_waitlist_notified_at
    BEFORE INSERT OR UPDATE OF status ON public.waitlist_entries
    FOR EACH ROW
    EXECUTE FUNCTION public.set_waitlist_notified_at();

DROP TRIGGER IF EXISTS set_waitlist_entries_updated_at
    ON public.waitlist_entries;

CREATE TRIGGER set_waitlist_entries_updated_at
    BEFORE UPDATE ON public.waitlist_entries
    FOR EACH ROW
    EXECUTE FUNCTION public.set_updated_at();

-- 6. Row-level security: only authenticated tenant members with operational
-- roles may access queue entries. No anonymous/public queue access.
ALTER TABLE public.waitlist_entries ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS waitlist_entries_operational_access
    ON public.waitlist_entries;

CREATE POLICY waitlist_entries_operational_access
    ON public.waitlist_entries
    FOR ALL
    TO authenticated
    USING (
        public.is_platform_admin()
        OR EXISTS (
            SELECT 1
            FROM public.tenant_memberships tm
            WHERE tm.tenant_id = waitlist_entries.tenant_id
              AND tm.profile_id = auth.uid()
              AND tm.role IN ('owner', 'admin', 'receptionist', 'staff')
        )
    )
    WITH CHECK (
        public.is_platform_admin()
        OR EXISTS (
            SELECT 1
            FROM public.tenant_memberships tm
            WHERE tm.tenant_id = waitlist_entries.tenant_id
              AND tm.profile_id = auth.uid()
              AND tm.role IN ('owner', 'admin', 'receptionist', 'staff')
        )
    );

REVOKE ALL ON TABLE public.waitlist_entries FROM anon, authenticated;

GRANT SELECT, INSERT, UPDATE, DELETE
    ON TABLE public.waitlist_entries TO authenticated;

-- The existing appointments policies still govern appointment access.
-- These column grants only permit authenticated callers to use the new link
-- column; they do not bypass appointments RLS.
GRANT SELECT (waitlist_entry_id)
    ON public.appointments TO authenticated;

GRANT INSERT (waitlist_entry_id)
    ON public.appointments TO authenticated;

GRANT UPDATE (waitlist_entry_id)
    ON public.appointments TO authenticated;

-- 7. Supabase Realtime publication. Skip safely if the publication is absent,
-- and avoid adding the table twice.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM pg_publication
        WHERE pubname = 'supabase_realtime'
    ) AND NOT EXISTS (
        SELECT 1
        FROM pg_publication_tables
        WHERE pubname = 'supabase_realtime'
          AND schemaname = 'public'
          AND tablename = 'waitlist_entries'
    ) THEN
        ALTER PUBLICATION supabase_realtime
            ADD TABLE public.waitlist_entries;
    END IF;
END
$$;

COMMENT ON TABLE public.waitlist_entries IS
    'Private tenant-scoped walk-in queue. Public websites must not write directly to this table.';

COMMIT;

-- Conversion transaction pattern:
-- 1) SELECT the waitlist row FOR UPDATE.
-- 2) INSERT the appointment with waitlist_entry_id = the entry id.
-- 3) UPDATE the same entry to status = 'converted' and set
--    converted_appointment_id = the new appointment id.
-- Commit all three steps together. The unique indexes prevent a second
-- appointment from claiming the same entry or two entries claiming one
-- appointment. Application/server logic must perform conversion atomically.

-- >>>>>>>>>> 00008_payments.sql >>>>>>>>>>
-- ============================================================================
-- Fides — Payments and refunds
-- Migration: 00008_payments.sql
-- Purpose: Record appointment payments and preserve financial records for
--          dashboard revenue aggregation and future BIR reporting.
--
-- Depends on:
--   public.tenants
--   public.profiles
--   public.tenant_memberships
--   public.appointments
--   public.customers
--   public.app_role
--   public.is_platform_admin()
--   public.set_updated_at()
--
-- Design notes:
--   * Monetary amounts use integer minor units (centavos for PHP).
--   * Payment records cannot be deleted by authenticated users.
--   * Refunds and voids are represented by status changes on the original row.
--   * Tenant-aware foreign keys prevent cross-tenant appointment/customer links.
--   * No Realtime publication changes are made.
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- 1. Enums
-- ----------------------------------------------------------------------------

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_type t
        JOIN pg_namespace n ON n.oid = t.typnamespace
        WHERE t.typname = 'payment_method'
          AND n.nspname = 'public'
    ) THEN
        CREATE TYPE public.payment_method AS ENUM (
            'cash',
            'gcash',
            'maya',
            'card',
            'bank_transfer',
            'other'
        );
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM pg_type t
        JOIN pg_namespace n ON n.oid = t.typnamespace
        WHERE t.typname = 'payment_status'
          AND n.nspname = 'public'
    ) THEN
        CREATE TYPE public.payment_status AS ENUM (
            'pending',
            'paid',
            'refunded',
            'voided',
            'failed'
        );
    END IF;
END
$$;

-- ----------------------------------------------------------------------------
-- 2. Payments
-- ----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.payments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    tenant_id UUID NOT NULL
        REFERENCES public.tenants(id) ON DELETE CASCADE,

    appointment_id UUID,
    customer_id UUID,

    amount_cents INTEGER NOT NULL DEFAULT 0
        CHECK (amount_cents >= 0),

    currency CHAR(3) NOT NULL DEFAULT 'PHP',

    method public.payment_method NOT NULL DEFAULT 'cash',

    status public.payment_status NOT NULL DEFAULT 'pending',

    reference TEXT,

    paid_at TIMESTAMPTZ,

    created_by UUID
        REFERENCES public.profiles(id) ON DELETE SET NULL,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    -- A linked appointment must belong to the same tenant.
    CONSTRAINT payments_appointment_fkey
        FOREIGN KEY (tenant_id, appointment_id)
        REFERENCES public.appointments (tenant_id, id)
        ON DELETE SET NULL (appointment_id),

    -- A linked customer must belong to the same tenant.
    CONSTRAINT payments_customer_fkey
        FOREIGN KEY (tenant_id, customer_id)
        REFERENCES public.customers (tenant_id, id)
        ON DELETE SET NULL (customer_id)
);

COMMENT ON TABLE public.payments IS
    'Tenant-scoped payment records for appointments, revenue reporting, and financial exports.';

COMMENT ON COLUMN public.payments.amount_cents IS
    'Payment amount in integer minor units; for PHP, this represents centavos.';

COMMENT ON COLUMN public.payments.currency IS
    'Three-character ISO currency code; defaults to PHP.';

COMMENT ON COLUMN public.payments.status IS
    'Current payment status. Refund and void operations retain the original payment row.';

COMMENT ON COLUMN public.payments.reference IS
    'Optional payment provider reference, transaction identifier, or receipt reference.';

COMMENT ON COLUMN public.payments.paid_at IS
    'Timestamp when the payment was received. Revenue reports use this timestamp.';

-- ----------------------------------------------------------------------------
-- 3. Indexes
-- ----------------------------------------------------------------------------

CREATE INDEX IF NOT EXISTS payments_tenant_paid_at_idx
    ON public.payments (tenant_id, paid_at);

CREATE INDEX IF NOT EXISTS payments_appointment_id_idx
    ON public.payments (appointment_id);

-- Supports customer self-service payment history.
CREATE INDEX IF NOT EXISTS payments_tenant_customer_id_idx
    ON public.payments (tenant_id, customer_id)
    WHERE customer_id IS NOT NULL;

-- Supports daily revenue queries for paid transactions.
CREATE INDEX IF NOT EXISTS payments_tenant_paid_revenue_idx
    ON public.payments (tenant_id, paid_at)
    WHERE status = 'paid';

-- ----------------------------------------------------------------------------
-- 4. updated_at trigger
-- ----------------------------------------------------------------------------

DROP TRIGGER IF EXISTS payments_set_updated_at
    ON public.payments;

CREATE TRIGGER payments_set_updated_at
    BEFORE UPDATE ON public.payments
    FOR EACH ROW
    EXECUTE FUNCTION public.set_updated_at();

-- ----------------------------------------------------------------------------
-- 5. Row Level Security
-- ----------------------------------------------------------------------------

ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;

-- Remove policies with these names if this migration is reapplied.
DROP POLICY IF EXISTS payments_operational_select
    ON public.payments;

DROP POLICY IF EXISTS payments_operational_insert
    ON public.payments;

DROP POLICY IF EXISTS payments_operational_update
    ON public.payments;

DROP POLICY IF EXISTS payments_customer_select
    ON public.payments;

-- Operational members may read payments in their tenant.
CREATE POLICY payments_operational_select
ON public.payments
FOR SELECT
TO authenticated
USING (
    public.is_platform_admin()
    OR EXISTS (
        SELECT 1
        FROM public.tenant_memberships tm
        WHERE tm.tenant_id = payments.tenant_id
          AND tm.profile_id = auth.uid()
          AND tm.role IN ('owner', 'admin', 'receptionist', 'staff')
    )
);

-- Operational members may create payments in their tenant.
CREATE POLICY payments_operational_insert
ON public.payments
FOR INSERT
TO authenticated
WITH CHECK (
    public.is_platform_admin()
    OR EXISTS (
        SELECT 1
        FROM public.tenant_memberships tm
        WHERE tm.tenant_id = payments.tenant_id
          AND tm.profile_id = auth.uid()
          AND tm.role IN ('owner', 'admin', 'receptionist', 'staff')
    )
);

-- Operational members may update payment records in their tenant.
-- Owners/admins may set any allowed payment status.
-- Receptionists/staff cannot set a payment to refunded or voided.
CREATE POLICY payments_operational_update
ON public.payments
FOR UPDATE
TO authenticated
USING (
    public.is_platform_admin()
    OR EXISTS (
        SELECT 1
        FROM public.tenant_memberships tm
        WHERE tm.tenant_id = payments.tenant_id
          AND tm.profile_id = auth.uid()
          AND tm.role IN ('owner', 'admin', 'receptionist', 'staff')
    )
)
WITH CHECK (
    public.is_platform_admin()
    OR EXISTS (
        SELECT 1
        FROM public.tenant_memberships tm
        WHERE tm.tenant_id = payments.tenant_id
          AND tm.profile_id = auth.uid()
          AND (
              tm.role IN ('owner', 'admin')
              OR (
                  tm.role IN ('receptionist', 'staff')
                  AND payments.status NOT IN ('refunded', 'voided')
              )
          )
    )
);

-- Customers may read only payments linked to their own customer record.
-- Customers receive no payment write policy.
CREATE POLICY payments_customer_select
ON public.payments
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1
        FROM public.customers c
        WHERE c.id = payments.customer_id
          AND c.tenant_id = payments.tenant_id
          AND c.profile_id = auth.uid()
    )
);

-- No DELETE policy is created. Payment rows must be retained.

-- ----------------------------------------------------------------------------
-- 6. Grants
-- ----------------------------------------------------------------------------

GRANT USAGE ON SCHEMA public TO authenticated;

REVOKE ALL ON public.payments FROM anon, authenticated;

GRANT SELECT, INSERT, UPDATE
ON public.payments
TO authenticated;

-- Deliberately do not grant DELETE.
-- RLS determines which payment rows each authenticated user may access.

COMMIT;

-- No Realtime publication changes are required for this migration.

