-- >>>>>>>>>> 00015_password_reset_codes.sql >>>>>>>>>>
-- ============================================================================
-- FIDES · Forgot-password codes (4-character email code)
-- Paste into the Supabase SQL Editor and run once. Idempotent.
--
-- Codes are stored HASHED (HMAC) and expire after 10 minutes. The table is
-- reachable only with the server's service-role/secret key: RLS is on and no
-- policy exists, so browsers can never read or write it.
-- ============================================================================
begin;

create table if not exists public.password_reset_codes (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users (id) on delete cascade,
  email            text not null,
  code_hash        text not null,
  attempts         integer not null default 0,
  expires_at       timestamptz not null,
  verified_at      timestamptz,
  reset_token_hash text,
  consumed_at      timestamptz,
  created_at       timestamptz not null default now()
);

create index if not exists password_reset_codes_email_idx on public.password_reset_codes (lower(email), created_at desc);
create index if not exists password_reset_codes_user_idx  on public.password_reset_codes (user_id);

alter table public.password_reset_codes enable row level security;
revoke all on public.password_reset_codes from anon, authenticated;

commit;

-- Make the new table visible to the API immediately (otherwise PostgREST may say it does not exist).
notify pgrst, 'reload schema';

-- >>>>>>>>>> 00016_tenant_membership_policy.sql >>>>>>>>>>
-- =============================================================================
-- Migration: 00002_tenant_membership_policy.sql
-- Purpose  : Allow authenticated users to read tenants they belong to via
--            either profiles.tenant_id or tenant_memberships.
-- =============================================================================

create or replace function public.get_my_tenant_id()
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select tenant_id from public.profiles where id = auth.uid()),
    (select tenant_id from public.tenant_memberships where profile_id = auth.uid() limit 1)
  );
$$;

create or replace function public.is_platform_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (auth.jwt() ->> 'role') in ('platform_admin', 'admin'),
    false
  )
  or exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'admin'
  );
$$;

drop policy if exists tenants_select_member_or_admin on public.tenants;
create policy tenants_select_member_or_admin
  on public.tenants for select
  to authenticated
  using (
    public.is_platform_admin()
    or id = public.get_my_tenant_id()
    or exists (
      select 1 from public.tenant_memberships
      where tenant_memberships.tenant_id = tenants.id
        and tenant_memberships.profile_id = auth.uid()
    )
    or exists (
      select 1 from public.profiles
      where profiles.tenant_id = tenants.id
        and profiles.id = auth.uid()
    )
  );

-- >>>>>>>>>> 00017_inquiries.sql >>>>>>>>>>
-- ============================================================================
-- Fides — Customer Inquiries Table & RLS Policies
-- Purpose: Store customer messages sent via the public provider contact form
--          and restrict dashboard visibility to authorized tenant members.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Create public.inquiries table
-- ----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.inquiries (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID REFERENCES public.tenants(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    email TEXT NOT NULL,
    phone TEXT,
    topic TEXT NOT NULL,
    message TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE public.inquiries IS
    'Customer inquiries and contact messages submitted through the provider website.';

-- Index for efficient querying within tenant dashboards
CREATE INDEX IF NOT EXISTS inquiries_tenant_id_created_at_idx
    ON public.inquiries (tenant_id, created_at DESC);

-- ----------------------------------------------------------------------------
-- 2. Enable Row Level Security (RLS)
-- ----------------------------------------------------------------------------

ALTER TABLE public.inquiries ENABLE ROW LEVEL SECURITY;

-- ----------------------------------------------------------------------------
-- 3. RLS Policy: Public/Anonymous INSERT
-- Allows visitors (both anon and authenticated) to submit contact messages.
-- ----------------------------------------------------------------------------

DROP POLICY IF EXISTS inquiries_insert_public ON public.inquiries;
CREATE POLICY inquiries_insert_public
    ON public.inquiries
    FOR INSERT
    TO anon, authenticated
    WITH CHECK (true);

-- ----------------------------------------------------------------------------
-- 4. RLS Policy: Tenant Members SELECT
-- Restricts viewing inquiries to members belonging to that specific tenant.
-- ----------------------------------------------------------------------------

DROP POLICY IF EXISTS inquiries_select_tenant_member ON public.inquiries;
CREATE POLICY inquiries_select_tenant_member
    ON public.inquiries
    FOR SELECT
    TO authenticated
    USING (
        EXISTS (
            SELECT 1 
            FROM public.tenant_memberships 
            WHERE tenant_memberships.tenant_id = inquiries.tenant_id 
            AND tenant_memberships.profile_id = auth.uid()
        )
    );

-- ----------------------------------------------------------------------------
-- 5. RLS Policy: Tenant Members UPDATE/DELETE
-- Allows tenant members to update or delete inquiries (e.g. mark as resolved)
-- ----------------------------------------------------------------------------
DROP POLICY IF EXISTS inquiries_modify_tenant_member ON public.inquiries;
CREATE POLICY inquiries_modify_tenant_member
    ON public.inquiries
    FOR ALL
    TO authenticated
    USING (
        EXISTS (
            SELECT 1 
            FROM public.tenant_memberships 
            WHERE tenant_memberships.tenant_id = inquiries.tenant_id 
            AND tenant_memberships.profile_id = auth.uid()
        )
    )
    WITH CHECK (
        EXISTS (
            SELECT 1 
            FROM public.tenant_memberships 
            WHERE tenant_memberships.tenant_id = inquiries.tenant_id 
            AND tenant_memberships.profile_id = auth.uid()
        )
    );

-- ----------------------------------------------------------------------------
-- 6. Privileges
-- ----------------------------------------------------------------------------

GRANT SELECT, INSERT ON public.inquiries TO anon, authenticated;
GRANT UPDATE, DELETE ON public.inquiries TO authenticated;

-- >>>>>>>>>> 00018_rejected_accounts.sql >>>>>>>>>>
-- ============================================================================
-- FIDES · Rejected-account history + decision date
-- Paste into the Supabase SQL Editor and run once. Idempotent (safe to re-run).
--
-- 1) public.rejected_accounts  - permanent, minimal record of every rejected
--    application. It is written BEFORE the application, documents and images
--    are deleted, so the email/details can be re-submitted while the admin
--    still sees who was rejected, why and when. It deliberately has NO foreign
--    key to account_applications / auth.users, so deleting those never touches it.
-- 2) account_applications.decided_at - the date an account was Approved (or
--    Rejected, for legacy rows that were kept). Shown on the Review Queue.
--
-- RLS is on with no policies: only the server (service-role/secret key) can read
-- or write these tables; browsers never can.
-- ============================================================================
begin;

create table if not exists public.rejected_accounts (
  id                uuid primary key default gen_random_uuid(),
  application_id    uuid unique,                 -- id the application had before deletion (no FK on purpose)
  reference_code    text,
  email             text not null,
  full_name         text not null,
  owner_legal_name  text,
  phone             text,
  business_name     text,
  business_type     text,                         -- account / business type
  location          text,                         -- "City, Province"
  plan_code         text,
  rejection_reason  text not null,
  submitted_at      timestamptz,
  rejected_at       timestamptz not null default now(),
  rejected_by       text not null default 'Platform administrator',
  email_sent        boolean not null default false,
  created_at        timestamptz not null default now()
);

create index if not exists rejected_accounts_email_idx       on public.rejected_accounts (lower(email));
create index if not exists rejected_accounts_rejected_at_idx on public.rejected_accounts (rejected_at desc);

alter table public.rejected_accounts enable row level security;
revoke all on public.rejected_accounts from anon, authenticated;

-- Date an application was approved / rejected.
alter table public.account_applications add column if not exists decided_at timestamptz;

update public.account_applications
   set decided_at = coalesce(approved_at, reviewed_at)
 where decided_at is null
   and status in ('approved', 'suspended', 'rejected');

commit;

-- Make the new table/column visible to the API immediately.
notify pgrst, 'reload schema';

-- >>>>>>>>>> 00019_document_upload_limit.sql >>>>>>>>>>
-- Raise the registration document upload limit from 5 MB to 50 MB.
-- (Supabase's global storage limit is 50 MiB; on the free plan this is the maximum.)

update storage.buckets
set file_size_limit = 52428800
where id = 'application-documents';

do $$
declare c record;
begin
  for c in
    select conrelid::regclass as tbl, conname
    from pg_constraint
    where contype = 'c' and pg_get_constraintdef(oid) ilike '%size_bytes%5242880%'
  loop
    execute format('alter table %s drop constraint %I', c.tbl, c.conname);
    execute format('alter table %s add constraint %I check (size_bytes is null or (size_bytes >= 0 and size_bytes <= 52428800)) not valid', c.tbl, c.conname);
  end loop;
end $$;
